import { rawAlias, rawMapping, rawScalar, rawSequence } from "./model.mjs";
import {
  countIndent,
  decodeDoubleQuoted,
  findTopLevelMappingColon,
  foldLines,
  splitLines,
  stripInlineComment,
  stripTrailingNewlines,
  trimEndSpaces,
  trimStartSpaces,
} from "./utils.mjs";

function isBlankOrComment(line) {
  const indent = countIndent(line);
  return indent >= line.length || line[indent] === "#";
}

function isSequenceIndicator(content) {
  return content.startsWith("-") && (content.length === 1 || content[1] === " " || content[1] === "\t" || content[1] === "#");
}

function attachProperties(node, properties) {
  if (properties.tag !== null && node.kind !== "raw-alias") {
    node.explicitTag = properties.tag;
  }
  if (properties.anchor !== null && node.kind !== "raw-alias") {
    node.anchor = properties.anchor;
  }
  return node;
}

class InlineParser {
  constructor(text) {
    this.text = text;
    this.index = 0;
  }

  skipSpaces() {
    while (this.index < this.text.length) {
      const char = this.text[this.index];
      if (char !== " " && char !== "\t") {
        break;
      }
      this.index += 1;
    }
  }

  atEnd() {
    this.skipSpaces();
    return this.index >= this.text.length || this.text[this.index] === "#";
  }

  readName() {
    const start = this.index;
    while (this.index < this.text.length) {
      const char = this.text[this.index];
      if (
        char === " " ||
        char === "\t" ||
        char === "," ||
        char === "]" ||
        char === "}" ||
        char === ":" ||
        char === "#"
      ) {
        break;
      }
      this.index += 1;
    }
    return this.text.slice(start, this.index);
  }

  readProperties() {
    let tag = null;
    let anchor = null;

    while (true) {
      this.skipSpaces();
      if (this.text.startsWith("!!", this.index)) {
        this.index += 2;
        tag = this.readName();
        continue;
      }
      if (this.text[this.index] === "&") {
        this.index += 1;
        anchor = this.readName();
        continue;
      }
      break;
    }

    return { tag, anchor };
  }

  parseSingleQuoted() {
    this.index += 1;
    let text = "";
    while (this.index < this.text.length) {
      const char = this.text[this.index];
      if (char === "'") {
        if (this.text[this.index + 1] === "'") {
          text += "'";
          this.index += 2;
        } else {
          this.index += 1;
          return rawScalar("single", text);
        }
      } else {
        text += char;
        this.index += 1;
      }
    }
