    this.skipSpaces();
    if (this.text[this.index] === "}") {
      this.index += 1;
      return rawMapping(entries);
    }

    while (true) {
      const start = this.index;
      let sliceEnd = this.index;
      while (sliceEnd < this.text.length) {
        const segment = this.text.slice(start, sliceEnd + 1);
        const colon = findTopLevelMappingColon(segment);
        if (colon >= 0) {
          const keyText = segment.slice(0, colon);
          const keyParser = new InlineParser(keyText);
          const key = keyParser.parseNode("");
          this.index = start + colon + 1;
          const value = this.parseNode(",}");
          entries.push({ key, value });
          break;
        }
        const char = this.text[sliceEnd];
        if (char === "," || char === "}") {
          throw new Error("Invalid flow mapping");
        }
        sliceEnd += 1;
      }

      this.skipSpaces();
      const next = this.text[this.index];
      if (next === ",") {
        this.index += 1;
        continue;
      }
      if (next === "}") {
        this.index += 1;
        break;
      }
      throw new Error("Invalid flow mapping");
    }

    return rawMapping(entries);
  }

  parseNode(stopChars = "") {
    this.skipSpaces();
    const properties = this.readProperties();
    this.skipSpaces();

    const char = this.text[this.index];
    let node;

    if (char === "*") {
      this.index += 1;
      node = rawAlias(this.readName());
    } else if (char === "[") {
      node = this.parseFlowSequence();
    } else if (char === "{") {
      node = this.parseFlowMapping();
    } else if (char === "\"") {
      node = this.parseDoubleQuoted();
    } else if (char === "'") {
      node = this.parseSingleQuoted();
    } else {
      node = this.parsePlain(stopChars);
    }

    return attachProperties(node, properties);
