class Parser {
  constructor(source) {
    this.lines = splitLines(source);
    this.index = 0;
  }

  peekMeaningful(from = this.index) {
    let cursor = from;
    while (cursor < this.lines.length) {
      if (!isBlankOrComment(this.lines[cursor])) {
        const indent = countIndent(this.lines[cursor]);
        return {
          index: cursor,
          indent,
          content: this.lines[cursor].slice(indent),
        };
      }
      cursor += 1;
    }
    return null;
  }

  consumeBlankLines() {
    while (this.index < this.lines.length && isBlankOrComment(this.lines[this.index])) {
      this.index += 1;
    }
  }

  parseDocument() {
    this.consumeBlankLines();
    const first = this.peekMeaningful();
    if (first === null) {
      return rawScalar("plain", "");
    }

    if (
      first.index === this.index &&
      first.content.startsWith("---") &&
      (first.content.length === 3 || first.content[3] === " " || first.content[3] === "\t" || first.content[3] === "#")
    ) {
      const remainder = trimStartSpaces(stripInlineComment(first.content.slice(3)));
      if (remainder.length === 0) {
        this.index += 1;
        this.consumeBlankLines();
        const next = this.peekMeaningful();
        if (next === null) {
          return rawScalar("plain", "");
        }
        return this.parseNodeAtIndent(next.indent);
      }
      return this.parseNodeWithContent(0, remainder, false, false);
    }

    return this.parseNodeAtIndent(first.indent);
  }

  parseNodeAtIndent(indent) {
    this.consumeBlankLines();
    const info = this.peekMeaningful();
    if (info === null || info.indent < indent) {
      return null;
    }
    return this.parseNodeWithContent(info.indent, info.content, false, false);
  }

  parseProperties(text) {
    let cursor = 0;
    let tag = null;
    let anchor = null;

    while (true) {
      while (cursor < text.length && (text[cursor] === " " || text[cursor] === "\t")) {
        cursor += 1;
      }

      if (text.startsWith("!!", cursor)) {
        cursor += 2;
        const start = cursor;
        while (cursor < text.length) {
          const char = text[cursor];
          if (char === " " || char === "\t" || char === "#") {
            break;
          }
          cursor += 1;
        }
        tag = text.slice(start, cursor);
        continue;
      }

      if (text[cursor] === "&") {
        cursor += 1;
        const start = cursor;
        while (cursor < text.length) {
          const char = text[cursor];
          if (char === " " || char === "\t" || char === "#") {
            break;
          }
          cursor += 1;
        }
        anchor = text.slice(start, cursor);
        continue;
      }

      break;
    }

    return {
      tag,
      anchor,
      rest: trimStartSpaces(text.slice(cursor)),
    };
  }

  parseNestedAfterEmpty(baseIndent, allowIndentlessSequence) {
    this.consumeBlankLines();
    const next = this.peekMeaningful();
    if (next === null) {
      return rawScalar("plain", "");
    }
    if (allowIndentlessSequence && next.indent === baseIndent && isSequenceIndicator(next.content)) {
      return this.parseNodeAtIndent(baseIndent);
    }
    if (next.indent > baseIndent) {
      return this.parseNodeAtIndent(next.indent);
    }
    return rawScalar("plain", "");
  }

  parseBlockScalarHeader(text) {
    let cursor = 1;
    let chomp = null;
    let explicitIndent = null;

    while (cursor < text.length) {
      const char = text[cursor];
      if (char === "+" || char === "-") {
        chomp = char;
        cursor += 1;
        continue;
      }
      if (char >= "1" && char <= "9") {
        explicitIndent = Number(char);
        cursor += 1;
        continue;
      }
      break;
    }

    const trailing = trimStartSpaces(stripInlineComment(text.slice(cursor)));
    if (trailing.length !== 0) {
      return null;
    }

    return {
      style: text[0],
      chomp,
      explicitIndent,
    };
  }

  parseBlockScalar(baseIndent, header, properties, lineConsumed) {
    const parsedHeader = this.parseBlockScalarHeader(header);
    if (parsedHeader === null) {
      return null;
    }

    if (!lineConsumed) {
      this.index += 1;
    }

    const collected = [];
    let contentIndent = parsedHeader.explicitIndent === null ? null : baseIndent + parsedHeader.explicitIndent;

    while (this.index < this.lines.length) {
      const line = this.lines[this.index];
      if (isBlankOrComment(line)) {
        const next = this.peekMeaningful(this.index + 1);
        if (next === null) {
          collected.push("");
          this.index += 1;
          continue;
        }
        if (contentIndent !== null && next.indent < contentIndent) {
          break;
        }
        collected.push("");
        this.index += 1;
        continue;
      }

      const indent = countIndent(line);
      if (contentIndent === null) {
        if (indent <= baseIndent) {
          break;
        }
        contentIndent = indent;
      }
      if (indent < contentIndent) {
        break;
      }

      collected.push(line.slice(contentIndent));
      this.index += 1;
    }

    let text = parsedHeader.style === "|" ? collected.join("\n") : foldLines(collected);
    if (parsedHeader.chomp === "-") {
      text = stripTrailingNewlines(text);
    } else if (parsedHeader.chomp === "+") {
      text = text;
    } else {
      text = stripTrailingNewlines(text) + "\n";
    }

    return rawScalar(parsedHeader.style === "|" ? "literal" : "folded", text, properties.tag, properties.anchor);
  }

  parsePlainScalar(baseIndent, firstText, properties, lineConsumed) {
    const lines = [stripInlineComment(firstText)];
    if (!lineConsumed) {
      this.index += 1;
    }

    while (this.index < this.lines.length) {
      const line = this.lines[this.index];

      if (isBlankOrComment(line)) {
        const next = this.peekMeaningful(this.index + 1);
        if (next === null || next.indent < baseIndent) {
          break;
        }
        lines.push("");
        this.index += 1;
        continue;
      }

      const indent = countIndent(line);
      if (indent < baseIndent) {
        break;
      }

      lines.push(stripInlineComment(line.slice(baseIndent)));
      this.index += 1;
    }

    return rawScalar("plain", foldLines(lines), properties.tag, properties.anchor);
  }

  parseStandaloneInline(text, properties) {
    const parser = new InlineParser(text);
    const node = parser.parseNode("");
    if (!parser.atEnd()) {
      throw new Error("Unexpected trailing content");
    }
    return attachProperties(node, properties);
  }

  parseMapping(baseIndent, firstContent, lineConsumed, properties) {
    const entries = [];
    let pending = firstContent;
    let pendingConsumed = lineConsumed;

    while (true) {
      let content;
      if (pending !== null) {
        content = pending;
        if (!pendingConsumed) {
          this.index += 1;
        }
        pending = null;
      } else {
        this.consumeBlankLines();
        const info = this.peekMeaningful();
        if (info === null || info.indent !== baseIndent) {
          break;
        }
        content = info.content;
        this.index += 1;
      }

      const colonIndex = findTopLevelMappingColon(content);
      if (colonIndex < 0) {
        throw new Error("Invalid mapping entry");
      }

      const keyText = content.slice(0, colonIndex);
      const valueText = trimStartSpaces(content.slice(colonIndex + 1));

      const key = this.parseStandaloneInline(keyText, { tag: null, anchor: null });
      const value = valueText.length === 0
        ? this.parseNestedAfterEmpty(baseIndent, true)
        : this.parseNodeWithContent(baseIndent + 2, valueText, true, false);

      entries.push({ key, value });
    }

    return rawMapping(entries, properties.tag, properties.anchor);
  }

  parseSequence(baseIndent, firstContent, lineConsumed, properties) {
    const items = [];
    let pending = firstContent;
    let pendingConsumed = lineConsumed;

    while (true) {
      let content;
      if (pending !== null) {
        content = pending;
        if (!pendingConsumed) {
          this.index += 1;
        }
        pending = null;
      } else {
        this.consumeBlankLines();
        const info = this.peekMeaningful();
        if (info === null || info.indent !== baseIndent || !isSequenceIndicator(info.content)) {
          break;
        }
        content = info.content;
        this.index += 1;
      }

      const remainder = trimStartSpaces(content.slice(1));
      const item = remainder.length === 0
        ? this.parseNestedAfterEmpty(baseIndent, false)
        : this.parseNodeWithContent(baseIndent + 2, remainder, true, false);
      items.push(item);
    }

    return rawSequence(items, properties.tag, properties.anchor);
  }

  parseNodeWithContent(baseIndent, content, lineConsumed, allowIndentlessSequence) {
    const properties = this.parseProperties(content);
    const remainder = properties.rest;

    if (remainder.length === 0) {
      const nested = this.parseNestedAfterEmpty(baseIndent, allowIndentlessSequence);
      return attachProperties(nested, properties);
    }

    const blockScalar = this.parseBlockScalar(baseIndent, remainder, properties, lineConsumed);
    if (blockScalar !== null) {
      return blockScalar;
    }

    if (isSequenceIndicator(remainder)) {
      return this.parseSequence(baseIndent, remainder, lineConsumed, properties);
    }

    if (findTopLevelMappingColon(remainder) >= 0) {
      return this.parseMapping(baseIndent, remainder, lineConsumed, properties);
    }

    const first = remainder[0];
    if (first === "[" || first === "{" || first === "\"" || first === "'" || first === "*") {
      if (!lineConsumed) {
        this.index += 1;
      }
      return this.parseStandaloneInline(remainder, properties);
    }

    return this.parsePlainScalar(baseIndent, remainder, properties, lineConsumed);
  }
}

export function parseYaml(source) {
  const parser = new Parser(source);
  return parser.parseDocument();
}

