export function rawScalar(style, text, explicitTag = null, anchor = null) {
  return {
    kind: "raw-scalar",
    style,
    text,
    explicitTag,
    anchor,
  };
}

export function rawSequence(items = [], explicitTag = null, anchor = null) {
  return {
    kind: "raw-sequence",
    items,
    explicitTag,
    anchor,
  };
}

export function rawMapping(entries = [], explicitTag = null, anchor = null) {
  return {
    kind: "raw-mapping",
    entries,
    explicitTag,
    anchor,
  };
}

export function rawAlias(name) {
  return {
    kind: "raw-alias",
    name,
  };
}

export function scalarNode(type, value, dumpText, extra = {}) {
  return {
    kind: "scalar",
    type,
    value,
    dumpText,
    ...extra,
  };
}

export function sequenceNode(items = [], anchor = null) {
  return {
    kind: "sequence",
    items,
    anchor,
  };
}

export function mappingNode(entries = [], anchor = null) {
  return {
    kind: "mapping",
    entries,
    anchor,
  };
}

export function isCollection(node) {
  return node.kind === "sequence" || node.kind === "mapping";
}

export function isScalar(node) {
  return node.kind === "scalar";
}

export function cloneEntry(entry) {
  return { key: entry.key, value: entry.value };
}

