function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isWhitespace(character) {
  return (
    character === ' ' ||
    character === '\t' ||
    character === '\n' ||
    character === '\r' ||
    character === '\f' ||
    character === '\v'
  );
}

function isNegativeIntegerToken(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  for (let index = 1; index < token.length; index += 1) {
    if (!isDigit(token[index])) {
      return false;
    }
  }

  return true;
}

function isNegativeDecimalToken(token) {
  if (token.length < 3 || token[0] !== '-') {
    return false;
  }

  let dotIndex = -1;
  for (let index = 1; index < token.length; index += 1) {
    const character = token[index];
    if (character === '.') {
      if (dotIndex !== -1) {
        return false;
      }

      dotIndex = index;
      continue;
    }

    if (!isDigit(character)) {
      return false;
    }
  }

  if (dotIndex === -1 || dotIndex === token.length - 1) {
    return false;
  }

  return true;
}

function isLongOptionLikeToken(token) {
  if (token.length < 2 || token[0] !== '-' || token[1] !== '-') {
    return false;
  }

  if (token.length === 2) {
    return true;
  }

  return token[2] !== '-';
}

function isShortOptionLikeToken(token) {
  if (token.length < 2 || token[0] !== '-' || token[1] === '-') {
    return false;
  }

  return !isWhitespace(token[1]);
}

export function canConsumeOptionValue(token) {
  if (token.length === 0) {
    return true;
  }

  if (token === '-') {
    return true;
  }

  if (token[0] !== '-') {
    return true;
  }

  if (isNegativeIntegerToken(token) || isNegativeDecimalToken(token)) {
    return true;
  }

  return !isLongOptionLikeToken(token) && !isShortOptionLikeToken(token);
}

