import { mappingNode, sequenceNode } from "./model.mjs";
import { resolveScalar, scalarEquals } from "./scalars.mjs";

function findKeyIndex(entries, key) {
  for (let index = 0; index < entries.length; index += 1) {
    if (scalarEquals(entries[index].key, key)) {
      return index;
    }
  }
  return -1;
}

function assignEntry(entries, key, value) {
  const index = findKeyIndex(entries, key);
  if (index >= 0) {
    entries[index].value = value;
  } else {
    entries.push({ key, value });
  }
}

function mergeEntries(entries, source) {
  if (source.kind === "mapping") {
    for (let index = 0; index < source.entries.length; index += 1) {
      const entry = source.entries[index];
      if (findKeyIndex(entries, entry.key) < 0) {
        entries.push({ key: entry.key, value: entry.value });
      }
    }
    return;
  }

  if (source.kind === "sequence") {
    for (let index = 0; index < source.items.length; index += 1) {
      mergeEntries(entries, source.items[index]);
    }
  }
}

function isMergeKey(node) {
  return node.kind === "scalar" && node.type === "string" && node.value === "<<";
}

function resolveNode(rawNode, anchors) {
  if (rawNode.kind === "raw-alias") {
    if (!anchors.has(rawNode.name)) {
      throw new Error(`Unknown anchor: ${rawNode.name}`);
    }
    return anchors.get(rawNode.name);
  }

  if (rawNode.kind === "raw-scalar") {
    const scalar = resolveScalar(rawNode);
    if (rawNode.anchor !== null) {
      anchors.set(rawNode.anchor, scalar);
    }
    return scalar;
  }

  if (rawNode.kind === "raw-sequence") {
    const sequence = sequenceNode([], rawNode.anchor);
    if (rawNode.anchor !== null) {
      anchors.set(rawNode.anchor, sequence);
    }
    for (let index = 0; index < rawNode.items.length; index += 1) {
      sequence.items.push(resolveNode(rawNode.items[index], anchors));
    }
    return sequence;
  }

  if (rawNode.kind === "raw-mapping") {
    const mapping = mappingNode([], rawNode.anchor);
    if (rawNode.anchor !== null) {
      anchors.set(rawNode.anchor, mapping);
    }
    for (let index = 0; index < rawNode.entries.length; index += 1) {
      const rawEntry = rawNode.entries[index];
      const key = resolveNode(rawEntry.key, anchors);
      const value = resolveNode(rawEntry.value, anchors);
      if (isMergeKey(key)) {
        mergeEntries(mapping.entries, value);
      } else {
        assignEntry(mapping.entries, key, value);
      }
    }
    return mapping;
  }

  throw new Error("Unsupported node type");
}

export function resolveYaml(rawNode) {
  return resolveNode(rawNode, new Map());
}

