export function countIndent(line) {
  let indent = 0;
  while (indent < line.length && line[indent] === " ") {
    indent += 1;
  }
  if (indent < line.length && line[indent] === "\t") {
    throw new Error("Tabs in indentation are not supported");
  }
  return indent;
}

export function splitLines(source) {
  if (source.length === 0) {
    return [];
  }

  const lines = [];
  let start = 0;
  for (let index = 0; index < source.length; index += 1) {
    if (source[index] === "\n") {
      let line = source.slice(start, index);
      if (line.endsWith("\r")) {
        line = line.slice(0, -1);
      }
      lines.push(line);
      start = index + 1;
    }
  }

  if (start < source.length) {
    let line = source.slice(start);
    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }
    lines.push(line);
  } else if (source.endsWith("\n")) {
    lines.push("");
  }

  return lines;
}

export function trimEndSpaces(text) {
  let end = text.length;
  while (end > 0 && (text[end - 1] === " " || text[end - 1] === "\t")) {
    end -= 1;
  }
  return text.slice(0, end);
}

export function trimStartSpaces(text) {
  let start = 0;
  while (start < text.length && (text[start] === " " || text[start] === "\t")) {
    start += 1;
  }
  return text.slice(start);
}

export function asciiLower(text) {
  let result = "";
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code >= 65 && code <= 90) {
      result += String.fromCharCode(code + 32);
    } else {
      result += text[index];
    }
  }
  return result;
}

function isWhitespace(char) {
  return char === " " || char === "\t";
}

function isCommentStart(text, index) {
  if (text[index] !== "#") {
    return false;
  }
  if (index === 0) {
    return true;
  }
  return isWhitespace(text[index - 1]);
}

export function stripInlineComment(text) {
  let depthSquare = 0;
  let depthCurly = 0;
