function basename(path) {
  let start = 0;
  for (let index = 0; index < path.length; index += 1) {
    const char = path[index];
    if (char === "/" || char === "\\") {
      start = index + 1;
    }
  }
  return path.slice(start) || path;
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`;
}

function formatUnrecognized(tokens) {
  if (tokens.length === 1) {
    return `unrecognized arguments: ${tokens[0]}`;
  }
  return `unrecognized arguments: ${tokens.join(" ")}`;
}

export function parseCommandLine(argv, scriptPath) {
  const programName = basename(scriptPath || "test15.mjs");

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === "-h" || token === "--help") {
      return { kind: "help", text: buildHelp(programName) };
    }
  }

  let value = null;
  let hasValue = false;
  let missingValue = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--a") {
      const next = argv[index + 1];
