        missingValue = true;
        break;
      }
      value = next;
      hasValue = true;
      index += 1;
      continue;
    }

    if (token.startsWith("--a=")) {
      value = token.slice(4);
      hasValue = true;
      continue;
    }

    extras.push(token);
  }

  if (missingValue) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, "argument --a: expected one argument"),
    };
  }

  if (!hasValue) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, "the following arguments are required: --a"),
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, formatUnrecognized(extras)),
