import {
  isYamlFloat,
  isYamlMap,
  isYamlSeq,
  isYamlTimestamp,
} from './types.mjs';

function spaces(count) {
  return ' '.repeat(count);
}

function scalarTagAndText(value) {
  if (value === null) {
    return { tag: '!!null', text: 'null' };
  }

  if (typeof value === 'boolean') {
    return { tag: '!!bool', text: value ? 'true' : 'false' };
  }

  if (typeof value === 'bigint') {
    return { tag: '!!int', text: value.toString() };
  }

  if (isYamlFloat(value)) {
    return { tag: '!!float', text: value.text };
  }

  if (isYamlTimestamp(value)) {
    return { tag: '!!timestamp', text: value.text };
  }

  return { tag: '', text: String(value) };
}

function toHex2(code) {
  const digits = '0123456789ABCDEF';
  return digits[(code >> 4) & 15] + digits[code & 15];
}

function quoteString(text) {
  let result = '"';

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    const code = char.charCodeAt(0);

    if (char === '\\') {
      result += '\\\\';
    } else if (char === '"') {
      result += '\\"';
    } else if (char === '\n') {
      result += '\\n';
    } else if (char === '\t') {
      result += '\\t';
    } else if (char === '\r') {
      result += '\\r';
    } else if (char === '\b') {
      result += '\\b';
    } else if (char === '\f') {
      result += '\\f';
    } else if (char === '\0') {
      result += '\\0';
    } else if (code < 32) {
      result += `\\x${toHex2(code)}`;
    } else {
      result += char;
    }
  }

  return `${result}"`;
}

function keyText(value) {
  if (typeof value === 'string') {
    return quoteString(value);
  }

  const scalar = scalarTagAndText(value);
  return `${scalar.tag} ${quoteString(scalar.text)}`;
}

function compareText(left, right) {
  if (left < right) {
    return -1;
  }

  if (left > right) {
    return 1;
  }

  return 0;
}

function sortEntries(entries) {
  return entries.slice().sort((left, right) => compareText(keyText(left.key), keyText(right.key)));
}

function countTrailingNewlines(text) {
  let count = 0;

  for (let index = text.length - 1; index >= 0; index -= 1) {
