      if (line.endsWith("\r")) {
        line = line.slice(0, -1);
      }
      lines.push(line);
      start = index + 1;
    }
  }

  if (start < source.length) {
    let line = source.slice(start);
    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }
    lines.push(line);
  } else if (source.endsWith("\n")) {
    lines.push("");
